<?php require 'config/db.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare('SELECT * FROM users WHERE email=?');$s->execute([$_POST['email']]);$u=$s->fetch();if($u&&password_verify($_POST['password'],$u['password'])){$_SESSION['user']=['id'=>$u['id'],'name'=>$u['name'],'role'=>$u['role']];header('Location:'.($u['role']==='admin'?'admin/dashboard.php':'index.php'));exit;}$msg='Invalid email or password.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login | DrinkShop</title><link rel="stylesheet" href="css/style.css"></head><body class="form-page"><div class="auth-shell"><aside class="auth-side"><div><div class="mark">🥤 DrinkShop</div><h2>Fresh drinks,<br>simple ordering.</h2><p>Sign in to order your favorite drinks and keep track of your orders.</p></div><div class="auth-points"><span>✓ Quick checkout</span><span>✓ Order tracking</span><span>✓ Delivery or pickup</span></div></aside><section class="auth-main"><div class="form-card"><div class="form-head"><h1>Welcome back</h1><p class="form-subtitle">Enter your account details to continue.</p></div><?php if($msg):?><div class="alert"><?=e($msg)?></div><?php endif;?><form method="post"><div class="field"><label>Email address</label><input type="email" name="email" placeholder="you@example.com" autocomplete="email" required></div><div class="field"><label>Password</label><input type="password" name="password" placeholder="Enter your password" autocomplete="current-password" required></div><button class="btn">Sign in</button></form><p class="form-foot">Don't have an account? <a href="register.php">Create account</a></p><p class="form-foot"><a href="index.php">← Back to shop</a></p></div></section></div></body></html>